// HasTenantSubscription applies the HasEdge predicate on the "tenant_subscription" edge.
func HasTenantSubscription() predicate.TenantEmailDomain {
	return predicate.TenantEmailDomain(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TenantSubscriptionTable, TenantSubscriptionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTenantSubscriptionWith applies the HasEdge predicate on the "tenant_subscription" edge with a given conditions (other predicates).
func HasTenantSubscriptionWith(preds ...predicate.TenantSubscription) predicate.TenantEmailDomain {
	return predicate.TenantEmailDomain(func(s *sql.Selector) {
		step := newTenantSubscriptionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TenantEmailDomain) predicate.TenantEmailDomain {
	return predicate.TenantEmailDomain(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TenantEmailDomain) predicate.TenantEmailDomain {
	return predicate.TenantEmailDomain(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TenantEmailDomain) predicate.TenantEmailDomain {
	return predicate.TenantEmailDomain(sql.NotPredicates(p))
}
